// Library extension method
public static IServiceCollection AddMyLibrary(this IServiceCollection services)
{
    services.TryAddSingleton<IClock, SystemClock>();
    services.TryAddScoped<IEmailSender, DefaultEmailSender>();
    services.AddScoped<IMyFeature, MyFeatureService>(); // always adds
    return services;
}

// App overrides the default email sender
builder.Services.AddMyLibrary();
builder.Services.AddScoped<IEmailSender, SendGridEmailSender>(); // wins

// TryAddScoped<IEmailSender, ...> in library would NOT override SendGrid

builder.Services.Configure<PaymentOptions>(
    builder.Configuration.GetSection("Payment"));

builder.Services.AddSingleton<IPaymentClient>(sp =>
{
    var opts = sp.GetRequiredService<IOptions<PaymentOptions>>().Value;
    return new PaymentClient(opts.ApiKey, opts.BaseUrl);
});

// Transient factory with scoped dependency — resolved per call
builder.Services.AddTransient<Func<AppDbContext>>(sp =>
    () => sp.GetRequiredService<AppDbContext>());

builder.Services.AddScoped<IOrderService, OrderService>();
builder.Services.Decorate<IOrderService, CachingOrderService>();

public sealed class CachingOrderService(
    IOrderService inner, // Scrutor injects the previous registration
    IMemoryCache cache) : IOrderService
{
    public async Task<OrderDto?> GetByIdAsync(Guid id, CancellationToken ct)
    {
        return await cache.GetOrCreateAsync($"order:{id}", async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return await inner.GetByIdAsync(id, ct);
        });
    }
}

builder.Services.AddScoped(typeof(IRepository<>), typeof(EfRepository<>));

// Resolves IRepository<Order> → EfRepository<Order> automatically
public sealed class OrderService(IRepository<Order> orders) : IOrderService { }

public class EfRepository<T>(AppDbContext db) : IRepository<T>
    where T : class
{
    public Task<T?> GetByIdAsync(Guid id, CancellationToken ct)
        => db.Set<T>().FindAsync([id], ct).AsTask()!;
}

